cat > server.js <<'EOF'
const net = require('net');
const { BAD_REQUEST_RESPONSE, PAYLOAD_TOO_LARGE_RESPONSE, routeRequest } = require('./router');
const { parseRequestHead } = require('./parser');

const PORT = process.env.PORT || 8080;
const DEFAULT_MAX_REQUEST_LINE_BYTES = 8192;
const MAX_HEAD_BYTES = 16384;
const MAX_BODY_BYTES = 1024 * 1024;
const LINE_END = '\r\n';
const HEAD_END = '\r\n\r\n';

const readMaxRequestLineBytes = () => {
  const configuredValue = process.env.MAX_REQUEST_LINE_BYTES ?? DEFAULT_MAX_REQUEST_LINE_BYTES;
  const maxRequestLineBytes = Number(configuredValue);
  if (!Number.isSafeInteger(maxRequestLineBytes) || maxRequestLineBytes <= 0) {
    throw new Error(`MAX_REQUEST_LINE_BYTES must be a positive integer, got "${configuredValue}"`);
  }
  return maxRequestLineBytes;
};

const MAX_REQUEST_LINE_BYTES = readMaxRequestLineBytes();

const isRequestLineTooLong = (receivedBytes) =>
  receivedBytes.length >= MAX_REQUEST_LINE_BYTES &&
  !receivedBytes.subarray(0, MAX_REQUEST_LINE_BYTES).includes(LINE_END);

const server = net.createServer((conn) => {
  let receivedBytes = Buffer.alloc(0);
  let requestHead = null;
  let bodyStart = 0;

  const sendResponse = (response) => conn.end(response, 'latin1');

  const handleReceivedBytes = () => {
    if (requestHead === null) {
      if (isRequestLineTooLong(receivedBytes)) return sendResponse(BAD_REQUEST_RESPONSE);

      const headEnd = receivedBytes.indexOf(HEAD_END);
      if (headEnd === -1) {
        if (receivedBytes.length > MAX_HEAD_BYTES) sendResponse(BAD_REQUEST_RESPONSE);
        return;
      }
      if (headEnd > MAX_HEAD_BYTES) return sendResponse(BAD_REQUEST_RESPONSE);

      requestHead = parseRequestHead(receivedBytes.toString('latin1', 0, headEnd));
      if (requestHead === null) return sendResponse(BAD_REQUEST_RESPONSE);
      if (requestHead.contentLength > MAX_BODY_BYTES) {
        return sendResponse(PAYLOAD_TOO_LARGE_RESPONSE);
      }
      bodyStart = headEnd + HEAD_END.length;
    }

    const bodyEnd = bodyStart + requestHead.contentLength;
    if (receivedBytes.length < bodyEnd) return;

    const { method, target, headers } = requestHead;
    sendResponse(routeRequest({ method, target, headers, body: receivedBytes.subarray(bodyStart, bodyEnd) }));
  };

  conn.on('error', () => {});
  conn.on('data', (chunk) => {
    if (conn.writableEnded) return;
    receivedBytes = Buffer.concat([receivedBytes, chunk]);
    handleReceivedBytes();
  });
  conn.on('end', () => {
    if (!conn.writableEnded) sendResponse(BAD_REQUEST_RESPONSE);
  });
});

server.listen(PORT);
EOF
